<script setup lang="ts">
import { annuity, buildRuntimePath, compilationResult, computePath, distributionPath, envelopePath, executionCosts, type ExecutionKey } from '~/utils/aiInvestmentModels'

const props = withDefaults(defineProps<{ view?: 'roi'|'distribution'|'compute'|'compilation'|'build-runtime'|'envelope'; locale?: 'nl'|'en' }>(), { view: 'compute', locale: 'nl' })
const nl = computed(() => props.locale === 'nl')
const money = (v:number, currency='$') => `${currency}${v >= 1 ? v.toFixed(v >= 100 ? 0 : 2) : v.toFixed(3)}${v >= 1 ? 'T' : 'T'}`
const num = (v:number,d=1) => new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{maximumFractionDigits:d}).format(v)
const clamp=(v:number,min:number,max:number)=>Math.max(min,Math.min(max,v))
const pct=(v:number)=>`${num(v,1)}%`

const roiDefaults={capex:5.2,life:10,rate:10,margin:40}
const roi=reactive({...roiDefaults})
const roiResult=computed(()=>{const a=annuity(roi.capex,roi.rate,roi.life);return {...a,requiredRevenue:a.annual/(roi.margin/100),ratio:a.annual/(roi.margin/100)/roi.capex}})
const roiPath=computed(()=>Array.from({length:roi.life+1},(_,year)=>({year,capital:roiResult.value.annual*year,revenue:roiResult.value.requiredRevenue*year})))
const roiPresets=[
 {id:'hardware',nl:'Hardware-zwaar',en:'Hardware-heavy',life:5,rate:14,margin:30},
 {id:'balanced',nl:'Gebalanceerd',en:'Balanced infrastructure',life:10,rate:10,margin:40},
 {id:'long',nl:'Langlevende infrastructuur',en:'Long-lived infrastructure',life:18,rate:7,margin:55}
]

const distDefaults={labourIncome:1,displacedPct:20,aiCostPct:25,labourMpc:90,capitalMpc:40,reemployedPct:50,replacementWagePct:80}
const dist=reactive({...distDefaults})
const distRows=computed(()=>distributionPath(dist)); const distLast=computed(()=>distRows.value.at(-1)!)

const computeDefaults={activityGrowth:35,efficiencyGrowth:30,acceleration:2,rebound:35,horizon:10}
const compute=reactive({...computeDefaults})
const computeRows=computed(()=>computePath(compute)); const computeLast=computed(()=>computeRows.value.at(-1)!)
const computeTaskPct=computed(()=>computeLast.value.perTask*100)
const taskPct=computed(()=>`${num(computeTaskPct.value,computeTaskPct.value<1?2:1)}%`)
const computePresets=[
 {id:'scale',nl:'Schaal groeit sneller',en:'Scaling wins',activityGrowth:55,efficiencyGrowth:20,acceleration:1,rebound:25},
 {id:'efficiency',nl:'Efficiëntie groeit sneller',en:'Efficiency wins',activityGrowth:22,efficiencyGrowth:48,acceleration:4,rebound:15},
 {id:'jevons',nl:'Jevons domineert',en:'Jevons dominates',activityGrowth:35,efficiencyGrowth:38,acceleration:2,rebound:120},
 {id:'balanced',nl:'Ongeveer in balans',en:'Balanced',activityGrowth:30,efficiencyGrowth:30,acceleration:0,rebound:0}
]

const compilationDefaults={frontier:27.5,small:22.5,specialist:25,deterministic:25}
const shares=reactive<Record<ExecutionKey,number>>({...compilationDefaults})
const maturity=ref(50)
const compilation=computed(()=>compilationResult(shares))
const executionKeys=Object.keys(executionCosts) as ExecutionKey[]
function setShare(key:ExecutionKey,value:number){
 const next=clamp(value,0,100),remaining=100-next,others=executionKeys.filter(k=>k!==key),old=others.reduce((s,k)=>s+shares[k],0)
 shares[key]=next
 others.forEach((k,i)=>shares[k]=i===others.length-1?100-next-others.slice(0,-1).reduce((s,o)=>s+shares[o],0):old?remaining*shares[k]/old:remaining/others.length)
}
function applyMaturity(value:number){maturity.value=value;const t=value/100;Object.assign(shares,{frontier:45-35*t,small:30-15*t,specialist:15+20*t,deterministic:10+30*t})}

const buildDefaults={projectYears:2,developmentCompute:300,transactionsM:2,runtimeFraction:2,systemLifetime:10}
const build=reactive({...buildDefaults})
const buildResult=computed(()=>buildRuntimePath({projectYears:build.projectYears,developmentCompute:build.developmentCompute,transactionsM:build.transactionsM,runtimeFraction:build.runtimeFraction,lifetime:build.systemLifetime}))
const buildLast=computed(()=>buildResult.value.rows.at(-1)!)

const envelopeDefaults={activityGrowth:35,efficiencyGrowth:28,architectureShift:35,installedGrowth:22,horizon:12}
const envelope=reactive({...envelopeDefaults})
const envelopeRows=computed(()=>envelopePath(envelope)); const envelopeLast=computed(()=>envelopeRows.value.at(-1)!)

function reset(){
 if(props.view==='roi')Object.assign(roi,roiDefaults)
 if(props.view==='distribution')Object.assign(dist,distDefaults)
 if(props.view==='compute')Object.assign(compute,computeDefaults)
 if(props.view==='compilation'){Object.assign(shares,compilationDefaults);maturity.value=50}
 if(props.view==='build-runtime')Object.assign(build,buildDefaults)
 if(props.view==='envelope')Object.assign(envelope,envelopeDefaults)
}
function seriesPoints(rows:any[],key:string,width=560,height=180,allKeys:string[]=[key]){
 const values=rows.flatMap(r=>allKeys.map(k=>Number(r[k])||0)),min=Math.min(0,...values),max=Math.max(...values,1),span=max-min||1
 return rows.map((r,i)=>`${20+i*(width-40)/Math.max(1,rows.length-1)},${height-18-(Number(r[key])-min)*(height-40)/span}`).join(' ')
}
const label=(key:string)=>({frontier:nl.value?'Frontier-LLM':'Frontier LLM',small:nl.value?'Klein model':'Small model',specialist:nl.value?'Beslis-/specialistisch model':'Decision/specialist model',deterministic:nl.value?'Deterministische software':'Deterministic software'} as Record<string,string>)[key]
</script>

<template>
 <section class="ai-model">
  <header class="model-head"><div><p class="model-kicker">{{nl?'Interactieve verkenning':'Interactive exploration'}}</p><h3>{{
   view==='roi'?(nl?'Welke omzet moet de infrastructuur dragen?':'What revenue must the infrastructure support?'):
   view==='distribution'?(nl?'Wie ontvangt de productiviteitswinst?':'Who receives the productivity gain?'):
   view==='compute'?(nl?'Groeit AI-gebruik even snel als rekenvraag?':'Does AI use grow as fast as compute demand?'):
   view==='compilation'?(nl?'Waar wordt intelligentie uitgevoerd?':'Where is intelligence executed?'):
   view==='build-runtime'?(nl?'Eenmalig bouwen of blijvend infereren?':'Build once or infer forever?'):
   (nl?'Wanneer ontstaat over- of ondercapaciteit?':'When does excess or insufficient capacity emerge?')
  }}</h3></div><button type="button" @click="reset">{{nl?'Herstel artikelaannames':'Reset article assumptions'}}</button></header>

  <template v-if="view==='roi'">
   <p class="question">{{nl?'Verander de financieringsaannames en zie hoeveel jaarlijkse omzet nodig is om het kapitaal te dragen.':'Change the financing assumptions and see how much annual revenue is needed to carry the capital.'}}</p>
   <div class="presets"><button v-for="p in roiPresets" :key="p.id" @click="Object.assign(roi,p)">{{nl?p.nl:p.en}}</button><small>{{nl?'Illustratieve configuraties':'Illustrative configurations'}}</small></div>
   <div class="model-grid"><div class="controls">
    <label><span>{{nl?'AI-infrastructuurinvestering':'AI infrastructure capex'}} <b>${{num(roi.capex,1)}}T</b></span><input v-model.number="roi.capex" type="range" min="1" max="10" step=".1"></label>
    <label><span>{{nl?'Economische levensduur':'Economic life'}} <b>{{roi.life}} {{nl?'jaar':'years'}}</b></span><input v-model.number="roi.life" type="range" min="3" max="20"></label>
    <label><span>{{nl?'Vereist rendement':'Required return'}} <b>{{roi.rate}}%</b></span><input v-model.number="roi.rate" type="range" min="3" max="20"></label>
    <label><span>{{nl?'Bijdragemarge':'Contribution margin'}} <b>{{roi.margin}}%</b></span><input v-model.number="roi.margin" type="range" min="10" max="80"></label>
   </div><div class="output"><div class="metrics"><div><span>{{nl?'Jaarlijkse kapitaallast':'Annual capital burden'}}</span><b>${{num(roiResult.annual*1000,0)}}B</b></div><div><span>{{nl?'Benodigde jaaromzet':'Required annual revenue'}}</span><b>${{num(roiResult.requiredRevenue,2)}}T</b></div><div><span>{{nl?'Omzet / capex per jaar':'Revenue / capex per year'}}</span><b>{{pct(roiResult.ratio*100)}}</b></div></div><svg viewBox="0 0 600 210" role="img"><line x1="20" y1="180" x2="580" y2="180" class="axis"/><polyline :points="seriesPoints(roiPath,'capital',560,180,['capital','revenue'])" class="line a"/><polyline :points="seriesPoints(roiPath,'revenue',560,180,['capital','revenue'])" class="line b"/><text x="22" y="202">0</text><text x="548" y="202">{{roi.life}} {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="a"/>{{nl?'cumulatieve kapitaallast':'cumulative capital burden'}}</span><span><i class="b"/>{{nl?'cumulatieve benodigde omzet':'cumulative required revenue'}}</span></div></div></div>
   <p class="interpretation">{{nl?`Bij deze aannames vraagt $${num(roi.capex,1)} biljoen aan kapitaal ongeveer $${num(roiResult.requiredRevenue,2)} biljoen omzet per jaar. Dit is een orde-groottecontrole, geen omzetprognose.`:`Under these assumptions, $${num(roi.capex,1)} trillion of capital requires about $${num(roiResult.requiredRevenue,2)} trillion in annual revenue. This is an order-of-magnitude check, not a revenue forecast.`}}</p>
  </template>

  <template v-else-if="view==='distribution'">
   <p class="question">{{nl?'Dezelfde kostenbesparing kan een andere consumptie-uitkomst geven, afhankelijk van wie het inkomen ontvangt.':'The same cost saving can produce a different consumption outcome depending on who receives the income.'}}</p>
   <div class="model-grid"><div class="controls">
    <label><span>{{nl?'Aanvankelijk arbeidsinkomen':'Initial labour income'}} <b>€{{num(dist.labourIncome,1)}}T</b></span><input v-model.number="dist.labourIncome" type="range" min=".2" max="3" step=".1"></label>
    <label><span>{{nl?'Verdrongen arbeidsinkomen':'Labour income displaced'}} <b>{{dist.displacedPct}}%</b></span><input v-model.number="dist.displacedPct" type="range" min="0" max="60"></label>
    <label><span>{{nl?'AI-kosten van verdrongen loon':'AI cost as share of displaced wages'}} <b>{{dist.aiCostPct}}%</b></span><input v-model.number="dist.aiCostPct" type="range" min="0" max="80"></label>
    <label><span>{{nl?'Herplaatst in ander werk':'Re-employed'}} <b>{{dist.reemployedPct}}%</b></span><input v-model.number="dist.reemployedPct" type="range" min="0" max="100"></label>
    <label><span>{{nl?'Vervangend loon':'Replacement wage'}} <b>{{dist.replacementWagePct}}%</b></span><input v-model.number="dist.replacementWagePct" type="range" min="20" max="120"></label>
    <details><summary>{{nl?'Consumptieaannames':'Consumption assumptions'}}</summary><label><span>{{nl?'Consumptiequote arbeidsinkomen':'Labour-income MPC'}} <b>{{dist.labourMpc}}%</b></span><input v-model.number="dist.labourMpc" type="range" min="30" max="100"></label><label><span>{{nl?'Consumptiequote kapitaalinkomen':'Capital-income MPC'}} <b>{{dist.capitalMpc}}%</b></span><input v-model.number="dist.capitalMpc" type="range" min="10" max="100"></label></details>
   </div><div class="output"><div class="metrics metrics-four"><div><span>{{nl?'Arbeidsinkomen na transitie':'Labour income after transition'}}</span><b>€{{num(distLast.labour,2)}}T</b></div><div><span>{{nl?'AI-leveranciersomzet':'AI supplier revenue'}}</span><b>€{{num(distLast.aiCost,2)}}T</b></div><div><span>{{nl?'Resterende bedrijfsbesparing':'Remaining company saving'}}</span><b>€{{num(distLast.companySavings,2)}}T</b></div><div><span>{{nl?'Verandering consumptievraag':'Change in consumption demand'}}</span><b>{{distLast.demandGap>=0?'+':''}}€{{num(distLast.demandGap*1000,0)}}B</b></div></div><svg viewBox="0 0 600 210"><line x1="20" y1="180" x2="580" y2="180" class="axis"/><polyline :points="seriesPoints(distRows,'labour',560,180,['labour','capital','consumption'])" class="line a"/><polyline :points="seriesPoints(distRows,'capital',560,180,['labour','capital','consumption'])" class="line b"/><polyline :points="seriesPoints(distRows,'consumption',560,180,['labour','capital','consumption'])" class="line c"/><text x="22" y="202">0</text><text x="548" y="202">10 {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="a"/>{{nl?'arbeidsinkomen':'labour income'}}</span><span><i class="b"/>{{nl?'kapitaalinkomen (leveranciers + besparing)':'capital income (suppliers + savings)'}}</span><span><i class="c"/>{{nl?'consumptievraag':'consumption demand'}}</span></div></div></div>
   <p class="interpretation">{{nl?`De productiviteitswinst verdwijnt niet, maar de gemodelleerde consumptievraag verandert met ${distLast.demandGap>=0?'plus':'min'} €${num(Math.abs(distLast.demandGap)*1000,0)} miljard. Prijzen, belastingen, transfers, vermogenseffecten en nieuwe bedrijfstakken zijn niet meegenomen.`:`The productivity gain does not disappear, but modelled consumption demand changes by ${distLast.demandGap>=0?'plus':'minus'} €${num(Math.abs(distLast.demandGap)*1000,0)} billion. Prices, taxes, transfers, wealth effects and new industries are excluded.`}}</p>
  </template>

  <template v-else-if="view==='compute'">
   <p class="question">{{nl?'Totale rekenvraag is het product van nuttige AI-activiteit en de rekenkracht per nuttige taak.':'Total compute demand is useful AI activity multiplied by compute required per useful task.'}}</p>
   <div class="presets"><button v-for="p in computePresets" :key="p.id" @click="Object.assign(compute,p)">{{nl?p.nl:p.en}}</button><small>{{nl?'Illustratieve scenario’s':'Illustrative scenarios'}}</small></div>
   <div class="model-grid"><div class="controls"><label><span>{{nl?'Groei nuttige AI-activiteit':'Useful AI activity growth'}} <b>{{compute.activityGrowth}}%/{{nl?'jr':'yr'}}</b></span><input v-model.number="compute.activityGrowth" type="range" min="0" max="150"></label><label><span>{{nl?'Efficiëntieverbetering':'Compute efficiency improvement'}} <b>{{compute.efficiencyGrowth}}%/{{nl?'jr':'yr'}}</b></span><input v-model.number="compute.efficiencyGrowth" type="range" min="0" max="90"></label><label><span>{{nl?'Versnelling door AI-R&D':'Acceleration from AI-assisted R&D'}} <b>{{compute.acceleration}}%</b></span><input v-model.number="compute.acceleration" type="range" min="0" max="15" step=".5"></label><label><span>{{nl?'Jevons-/reboundreactie':'Jevons / rebound response'}} <b>{{compute.rebound}}%</b></span><input v-model.number="compute.rebound" type="range" min="0" max="200"></label><label><span>{{nl?'Horizon':'Horizon'}} <b>{{compute.horizon}} {{nl?'jaar':'years'}}</b></span><input v-model.number="compute.horizon" type="range" min="5" max="20"></label></div><div class="output"><div class="metrics"><div><span>{{nl?'Nuttige AI-activiteit':'Useful AI activity'}}</span><b>{{num(computeLast.activity,1)}}×</b></div><div><span>{{nl?'Rekenkracht per taak':'Compute per task'}}</span><b>{{taskPct}} <small>{{nl?'van beginwaarde':'of baseline'}}</small></b></div><div><span>{{nl?'Totale rekenvraag':'Total compute demand'}}</span><b>{{num(computeLast.total,1)}}×</b></div></div><div class="compute-charts"><div><p class="chart-title">{{nl?'AI-activiteit en totale rekenvraag · × beginwaarde':'AI activity and total compute · × baseline'}}</p><svg viewBox="0 0 600 210" role="img" :aria-label="nl?'Nuttige AI-activiteit en totale rekenvraag door de tijd':'Useful AI activity and total compute demand over time'"><line x1="20" y1="172" x2="580" y2="172" class="axis"/><polyline :points="seriesPoints(computeRows,'activity',560,190,['activity','total'])" class="line a"/><polyline :points="seriesPoints(computeRows,'total',560,190,['activity','total'])" class="line c"/><text x="22" y="202">0</text><text x="540" y="202">{{compute.horizon}} {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="a"/>{{nl?'activiteit':'activity'}}</span><span><i class="c"/>{{nl?'totale compute':'total compute'}}</span></div></div><div><p class="chart-title">{{nl?'Rekenkracht per taak · eigen schaal (100% → 0%)':'Compute per task · separate scale (100% → 0%)'}}</p><svg viewBox="0 0 600 155" role="img" :aria-label="nl?'Resterende rekenkracht per taak als percentage van het begin':'Remaining compute per task as a percentage of baseline'"><line x1="20" y1="127" x2="580" y2="127" class="axis"/><line x1="20" y1="22" x2="580" y2="22" class="guide"/><polyline :points="seriesPoints(computeRows,'perTask',560,145)" class="line b"/><text x="22" y="18">100%</text><text x="22" y="148">0%</text><text x="540" y="148">{{compute.horizon}} {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="b"/>{{nl?'compute per taak':'compute per task'}}: {{taskPct}} {{nl?'over':'remaining'}}</span></div></div></div></div></div>
   <p class="interpretation">{{nl?`Onder deze aannames groeit economisch nuttige AI-activiteit ${num(computeLast.activity,1)}×, terwijl totale rekenvraag ${num(computeLast.total,1)}× wordt. De rekenvraag per taak daalt tot ${taskPct.value} van de beginwaarde; via rebound kan goedkopere compute ook extra gebruik uitlokken.`:`Under these assumptions, economically useful AI activity grows ${num(computeLast.activity,1)}× while total compute demand becomes ${num(computeLast.total,1)}×. Compute per task falls to ${taskPct.value} of its baseline; cheaper compute can also induce additional use through rebound.`}}</p>
  </template>

  <template v-else-if="view==='compilation'">
   <p class="question">{{nl?'Verdeel honderd taken over generatieve modellen, gespecialiseerde modellen en gewone software.':'Route one hundred tasks across generative models, specialist models and ordinary software.'}}</p>
   <div class="maturity"><label><span>{{nl?'Automatiseringsrijpheid':'Automation maturity'}} <b>{{maturity}}%</b></span><input :value="maturity" type="range" min="0" max="100" @input="applyMaturity(Number(($event.target as HTMLInputElement).value))"></label></div>
   <div class="compilation-layout"><div class="controls"><label v-for="key in executionKeys" :key="key"><span>{{label(key)}} <b>{{num(shares[key],0)}}%</b></span><input :value="shares[key]" type="range" min="0" max="100" @input="setShare(key,Number(($event.target as HTMLInputElement).value))"><small>{{nl?'relatieve rekeneenheden per taak':'relative compute units per task'}}: {{executionCosts[key]}}</small></label></div><div class="pipeline"><div v-for="key in executionKeys" :key="key" class="flow"><span>{{label(key)}}</span><div><i :style="{width:`${shares[key]}%`}"/></div><b>{{num(shares[key],0)}} {{nl?'taken':'tasks'}}</b></div><div class="compile-total"><span>{{nl?'Gemiddelde terugkerende compute':'Average recurring compute'}}</span><b>{{num(compilation.average,2)}} / 100</b><small>{{pct(compilation.reduction)}} {{nl?'lager dan alles via frontier-LLM':'below all-frontier-LLM execution'}}</small></div></div></div>
   <p class="interpretation">{{nl?`${num(compilation.generative,0)}% van de taken gebruikt nog generatieve inferentie. De kosten zijn genormaliseerde illustraties; ze vergelijken architecturen en zijn geen benchmark van specifieke producten.`:`${num(compilation.generative,0)}% of tasks still use generative inference. Costs are normalized illustrations comparing architectures, not benchmarks of particular products.`}}</p>
  </template>

  <template v-else-if="view==='build-runtime'">
   <p class="question">{{nl?'Vergelijk een systeem waarin het LLM in productie blijft met een systeem waarin AI tijdens de bouw deterministische software helpt maken.':'Compare a system that keeps an LLM in production with one where AI helps create deterministic software during development.'}}</p>
   <div class="model-grid"><div class="controls"><label><span>{{nl?'Projectduur':'Project duration'}} <b>{{build.projectYears}} {{nl?'jaar':'years'}}</b></span><input v-model.number="build.projectYears" type="range" min="1" max="5"></label><label><span>{{nl?'AI-compute tijdens ontwikkeling':'AI compute during development'}} <b>{{build.developmentCompute}}</b></span><input v-model.number="build.developmentCompute" type="range" min="50" max="1000" step="10"></label><label><span>{{nl?'Runtime-transacties':'Runtime transactions'}} <b>{{build.transactionsM}}M/{{nl?'jr':'yr'}}</b></span><input v-model.number="build.transactionsM" type="range" min=".1" max="10" step=".1"></label><label><span>{{nl?'AI-aandeel deterministische runtime':'AI runtime fraction after deployment'}} <b>{{build.runtimeFraction}}%</b></span><input v-model.number="build.runtimeFraction" type="range" min="0" max="25" step=".5"></label><label><span>{{nl?'Systeemlevensduur':'System lifetime'}} <b>{{build.systemLifetime}} {{nl?'jaar':'years'}}</b></span><input v-model.number="build.systemLifetime" type="range" min="5" max="20"></label></div><div class="output"><div class="metrics"><div><span>{{nl?'Cumulatief: LLM-runtime':'Cumulative: LLM runtime'}}</span><b>{{num(buildLast.cumulativeA,0)}}</b></div><div><span>{{nl?'Cumulatief: deterministisch':'Cumulative: deterministic'}}</span><b>{{num(buildLast.cumulativeB,0)}}</b></div><div><span>{{nl?'Omslagpunt':'Break-even'}}</span><b>{{buildResult.breakEven===null?(nl?'niet bereikt':'not reached'):`${nl?'jaar':'year'} ${buildResult.breakEven}`}}</b></div></div><svg viewBox="0 0 600 210"><line x1="20" y1="180" x2="580" y2="180" class="axis"/><polyline :points="seriesPoints(buildResult.rows,'cumulativeA',560,180,['cumulativeA','cumulativeB'])" class="line a"/><polyline :points="seriesPoints(buildResult.rows,'cumulativeB',560,180,['cumulativeA','cumulativeB'])" class="line b"/><text x="22" y="202">0</text><text x="540" y="202">{{build.systemLifetime}} {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="a"/>{{nl?'LLM blijft in runtime':'LLM remains at runtime'}}</span><span><i class="b"/>{{nl?'AI bouwt deterministische runtime':'AI builds deterministic runtime'}}</span></div></div></div>
   <p class="interpretation">{{nl?'Een hogere ontwikkelpiek kan zichzelf terugverdienen wanneer dezelfde logica vaak en lang genoeg zonder generatieve inferentie wordt uitgevoerd. Niet ieder probleem kan veilig of volledig worden gecompileerd.':'A higher development spike can repay itself when the same logic runs often and long enough without generative inference. Not every problem can be safely or fully compiled.'}}</p>
  </template>

  <template v-else>
   <p class="question">{{nl?'Vergelijk geïnstalleerde capaciteit met de rekenvraag die overblijft na efficiëntie en verschuiving naar goedkopere architecturen.':'Compare installed capacity with compute demand after efficiency gains and migration to cheaper architectures.'}}</p>
   <div class="model-grid"><div class="controls"><label><span>{{nl?'Groei economische AI-activiteit':'Economic AI activity growth'}} <b>{{envelope.activityGrowth}}%</b></span><input v-model.number="envelope.activityGrowth" type="range" min="0" max="100"></label><label><span>{{nl?'Efficiëntiegroei':'Efficiency growth'}} <b>{{envelope.efficiencyGrowth}}%</b></span><input v-model.number="envelope.efficiencyGrowth" type="range" min="0" max="80"></label><label><span>{{nl?'Verschuiving naar goedkopere uitvoering':'Migration to cheaper execution'}} <b>{{envelope.architectureShift}}%</b></span><input v-model.number="envelope.architectureShift" type="range" min="0" max="90"></label><label><span>{{nl?'Groei geïnstalleerde capaciteit':'Installed-capacity growth'}} <b>{{envelope.installedGrowth}}%</b></span><input v-model.number="envelope.installedGrowth" type="range" min="0" max="80"></label><label><span>{{nl?'Horizon':'Horizon'}} <b>{{envelope.horizon}} {{nl?'jaar':'years'}}</b></span><input v-model.number="envelope.horizon" type="range" min="5" max="20"></label></div><div class="output"><div class="metrics"><div><span>{{nl?'Geïnstalleerde capaciteit':'Installed capacity'}}</span><b>{{num(envelopeLast.installed,1)}}×</b></div><div><span>{{nl?'Benodigde capaciteit':'Required capacity'}}</span><b>{{num(envelopeLast.required,1)}}×</b></div><div><span>{{nl?'Benutting':'Utilization'}}</span><b>{{pct(envelopeLast.utilization)}}</b></div></div><svg viewBox="0 0 600 210"><line x1="20" y1="180" x2="580" y2="180" class="axis"/><polyline :points="seriesPoints(envelopeRows,'installed',560,180,['installed','required'])" class="line a"/><polyline :points="seriesPoints(envelopeRows,'required',560,180,['installed','required'])" class="line b"/><text x="22" y="202">1×</text><text x="540" y="202">{{envelope.horizon}} {{nl?'jaar':'years'}}</text></svg><div class="legend"><span><i class="a"/>{{nl?'geïnstalleerd':'installed'}}</span><span><i class="b"/>{{nl?'benodigd':'required'}}</span></div></div></div>
   <p class="interpretation">{{envelopeLast.gap>0?(nl?`In dit scenario ligt de geïnstalleerde capaciteit ${num(envelopeLast.gap,1)} genormaliseerde eenheden boven de berekende vraag. Dat is potentiële onderbenutting, niet automatisch bewijs van een zeepbel.`:`In this scenario, installed capacity exceeds calculated demand by ${num(envelopeLast.gap,1)} normalized units. That is potential underutilization, not automatic proof of a bubble.`):(nl?`In dit scenario ligt de berekende vraag ${num(-envelopeLast.gap,1)} eenheden boven de geïnstalleerde capaciteit.`:`In this scenario, calculated demand exceeds installed capacity by ${num(-envelopeLast.gap,1)} units.`)}}</p>
